def split_csv(line):
    if line == "":
        return [""]

    fields = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        # closing quote
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(c)
                    i += 1
            if not closed:
                return None  # unterminated quoted field
            # closing quote must be followed by comma or end of line
            if i == n:
                fields.append(''.join(chars))
                break
            elif line[i] == ',':
                fields.append(''.join(chars))
                i += 1
                # continue to next field
            else:
                return None
        else:
            # unquoted field
            comma_index = line.find(',', i)
            if comma_index == -1:
                field = line[i:]
                if '"' in field:
                    return None
                fields.append(field)
                break
            else:
                field = line[i:comma_index]
                if '"' in field:
                    return None
                fields.append(field)
                i = comma_index + 1

    return fields

